import './Header.css';

interface HeaderProps {
  connected: boolean;
}

export default function Header({ connected }: HeaderProps) {
  return (
    <div className="header">
      <span className="logo">engin</span>
      <span
        className="connection-dot"
        style={{ backgroundColor: connected ? 'green' : 'red' }}
      />
    </div>
  );
}

.header {
  height: var(--engin-header-height);
  background: var(--engin-bg-secondary);
  border-bottom: 1px solid var(--engin-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--engin-space-md);
  flex-shrink: 0;
}

.logo {
  font-weight: 700;
  color: var(--engin-accent);
  font-size: 18px;
}

.connection-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

